int reject_key_and_link(struct key* key, unsigned timeout, unsigned error, struct key* keyring, struct key* authkey) {
    if (!key || !keyring) {
        return -EINVAL;
    }

    if (key->flags & KEY_FLAG_INSTANTIATED) {
        return -EEXIST;
    }

    if (timeout > (UINT_MAX - jiffies)) {
        return -EOVERFLOW;
    }

    key->flags |= KEY_FLAG_NEGATIVE;
    key->expiry = jiffies + timeout;
    key->error = error;

    int ret = key_link(keyring, key);
    if (ret != 0) {
        return ret;
    }

    if (authkey) {
        key_revoke(authkey);
    }

    if (key->flags & KEY_FLAG_CONSTRUCTED) {
        wake_up_all(&key->wait);
    }

    mark_key_for_gc(key);

    return 0;
}
